	/**  `manual` or `daily`. */
	firmware_check: string,
	/**  The voice provider: `say` (macOS) or another a later version adds. */
	tts_provider: string,
	/**
	 *  What runs when a device of each kind is plugged in (`gearOnConnect`). Backup also
	 *  needs `auto_backup`.
	 */
