/**  A step that failed on a device, and why. */
export type StepFailure = {
	/**  The link (`link_handle`). */
	handle: string,
	device: string | null,
	/**  `Unmount`, `Backup`, `Card check`, ... */
	step: string,
	message: string,
	at: string,
};

/**  One step of an apply: Back up, Write, Read back, Verify. */
export type StepReport = {
	name: string,
	state: StepState,
	detail?: string | null,
};

/**  How one step of an apply ended. */
export type StepState = "done" | "failed" | 
/**  Not reached: an earlier step failed. */
"skipped";

export type Stick = "roll" | "pitch" | "throttle" | "yaw";

/**  The channel a stick drives, and the weight its mix gives it. */
export type StickChannel = {
	stick: Stick,
	/**  1 is CH1. */
	ch: number,
	/**  Percent; negative when reversed. */
	weight: number,
};

/**  The stick channels the sim starts from. */
export type StickMap = {
	/**  1 is CH1. */
	roll: number,
	pitch: number,
	throttle: number,
	yaw: number,
	/**  `your radio model`, or `EdgeTX's default order (AETR)`. */
	source: string,
	/**  The model gave every stick's channel, so a quick check is enough. */
	known: boolean,
};

/**  `gear_stop`: a running job's link (`GearJob.handle`). */
export type StopParams = {
	handle: string,
};

/**  Sizes in the gear folder. */
export type StorageView = {
	gear_dir: string,
	/**  Blobs, manifests and logs. */
	total_bytes: number,
	blobs: number,
	blob_bytes: number,
	/**  Blobs that more than one device names. */
	shared_blob_bytes: number,
	manifest_bytes: number,
	log_bytes: number,
	snapshots: number,
	devices: DeviceStorage[],
};

/**  `suggest`: changes to clip plans. Without `editor`, an agent made them. */
export type SuggestParams = {
	patches: PlanPatch[],
	editor?: Editor | null,
};

/**  Which fields of a plan an agent wrote and the user has not edited since. */
export type Suggested = {
	date: boolean,
	name: boolean,
	note: boolean,
	skip: boolean,
	cuts?: boolean,
	meta?: boolean,
};

/**  A control the sim will use, and where the suggestion came from. */
export type SuggestedControl = {
	control: RadioControl,
	/**  `SA down`, `CH5`. */
	label: string,
	/**  `your radio model`, `the quad's modes`. */
	source: string,
};

export type Summary = {
	results: ClipResult[],
	imported: number,
	skipped: number,
	failed: number,
	total_bytes: number,
	output_dir: string | null,
	/**  Ok when the format step may unlock, else the reason it stays locked. */
	format_ready: SerdeResult<null, string>,
};

/**
 *  The head's values for the other state of the join: the file's own while the join is on,
 *  the whole recording's while it is off. Turning the join on or off swaps them in.
 */
export type Swap = {
	duration: number | null,
	probe: Probe | null,
	signal: SignalScan | null,
	detail: string,
};

/**  The switch map of one aircraft. */
export type SwitchMap = {
	/**  The model's header name. */
	model?: string | null,
	/**  What was read: file names, with the backup date once backups exist. */
	sources: string[],
	rows: ControlRow[],
	sticks: StickChannel[],
	modes: AuxMode[],
	adjustments: Adjustment[],
	/**
	 *  Two modes on one range, a control with no effect, a mode no control reaches, a
	 *  sound file the card does not have.
	 */
	conflicts: string[],
	notes: string[],
	/**  Logical switches left out of the positions, with their condition. */
	unmapped?: Unmapped[],
	live?: Live | null,
};

/**  `gear_switch_map`: what to read, and whether to mark the live positions. */
export type SwitchMapParams = {
	/**  An EdgeTX card (its mount or a copy of its folder), or one model file. */
	radio?: string | null,
	/**  The model file on the card (`model01.yml`); default: the radio's selected model. */
	model?: string | null,
	/**
	 *  Betaflight `dump all`, `diff all` or CLI-line files, read in order: a later file's
	 *  lines win.
	 */
	fc?: string[],
	/**
	 *  An aircraft profile: the latest backups of the saved devices linked to it (its radio
	 *  and its FC). The radio's model is the one whose name the profile's EdgeTX models
	 *  list, else the radio's selected model.
	 */
	aircraft?: string | null,
	/**  Saved device ids whose latest backups to read: an FC's dump, a radio's card. */
	devices?: string[],
	/**
	 *  Mark where each control is now: the FC's channels (`MSP_RC`) when an FC is plugged
	 *  in, else the radio's joystick.
	 */
	live?: boolean,
	/**  The FC's port for `live`; omitted when one FC is plugged in. */
	port?: string | null,
	/**  Channel values to mark instead (µs, CH1 first). */
	channels?: number[],
};

export type SwitchWarning = {
	/**  `SA`. */
	switch: string,
	/**  `up`, `mid` or `down`. */
	pos: string,
};

/**  What a snapshot run did. */
export type TakeReport = {
	/**  The new snapshot, or the latest one when nothing changed. */
	backup: Backup,
	/**  False when the files equal the latest snapshot's: nothing was written. */
	new: boolean,
	/**  Files read and hashed. */
	read: number,
	/**  Files whose size and time matched the latest snapshot: not read. */
	skipped: number,
	bytes_read: number,
	/**  What happened to the card's logs. */
	logs: LogCounts,
};

/**  The long library jobs. */
export type Task = "rebuild" | "cuts" | "thumbnails" | "moments";

/**  The throttle curve of a rate profile. */
export type ThrottleView = {
	mid: number | null,
	expo: number | null,
	/**  `thr_hover`, when the firmware has it. */
	hover: number | null,
	/**  `off`, `scale` or `clip`. */
	limit: string,
	limit_percent: number | null,
	/**  Output (0-1) at stick `i / STEPS`. */
	curve: (number | null)[],
};

export type Timer = {
	/**  0 is Timer 1. */
	index: number,
	name: string,
	/**  The switch that runs it (`L1`, `NONE`). */
	swtch: string,
	mode: string,
	/**  The stored count, in seconds. */
	value: number,
	/**  0 off, 1 per flight, 2 until a manual reset. */
	persistent: string,
	/**  Every field, raw, in file order. */
	fields: Field[],
};

export type Tools = {
	ffmpeg: string,
	ffprobe: string,
};

/**  Totals for the footer. */
export type Totals = {
	clips: number,
	bytes: number,
	seconds: number | null,
	flying: number | null,
};

export type TrashReport = {
	trashed: string[],
	failed: ([string, string])[],
	/**  Where each file went, so `library_untrash` can put it back. */
	moved: Moved[],
};

/**  One flight's worst link, for the range trend. */
export type TrendPoint = {
	flight: string,
	start: string,
	worst_lq: number | null,
	worst_rssi_db: number | null,
};

/**  Why a backup was taken. */
export type Trigger = 
/**  Plugged in, with "Back up on connect" on. */
"connect" | 
/**  The person asked. */
"manual" | 
/**  Taken by the apply engine before a write. Always kept. */
"before_apply" | 
/**  Taken before a firmware flash. Always kept. */
"before_flash" | 
/**
 *  Read back from an FC right after an apply, so the next plan compares with what the
 *  FC holds now. Thinned like plug-in backups.
 */
"after_apply" | 
/**
 *  Taken from an old backup folder (`gear import-backups`). Thinned like plug-in
 *  backups.
 */
"import";

export type Tunables = {
	/**  A gap over this many seconds between rows starts a new armed segment. */
	segment_gap_s: number | null,
	/**  A gap over this many minutes between segments starts a new session. */
	session_gap_min: number | null,
	/**  Slack, in seconds, allowed when a clip claims segments. */
	tolerance_s: number | null,
	/**  A log day further than this from the import date means the radio clock reset. */
	max_log_age_days: number,
	/**
	 *  A clip with its own clock (DJI) takes a matching log's time only when the log starts
	 *  within this many seconds of the clip clock.
	 */
	clock_skew_s?: number | null,
};

/**  A logical switch the map cannot work out: it reads telemetry, a timer or sticky state. */
export type Unmapped = {
	/**  `L5`. */
	switch: string,
	/**  `telemetry`, `timer`, `sticky` or `depends`. */
	kind: string,
	/**  Its condition as text (`RxBt < 3.30`). */
	condition: string,
	/**  Controls it reads (`SA`). */
	reads: string[],
	/**  What uses it (`Plays "lowbat"`, `CH7 mix`, `L6`). */
	used_by: string[],
};

/**  `library_untrash`: the files `library_trash` moved. */
export type UntrashParams = {
	moved: Moved[],
};

/**  What a USB device says about itself. */
export type UsbInfo = {
	vid: number,
	pid: number,
	vendor?: string | null,
	product?: string | null,
	/**  The USB serial number. EdgeTX radios report a generic one, so it is not an id. */
	serial?: string | null,
	/**  `bcdDevice` as `major.minor` (an EdgeTX radio reports its firmware's, `2.12`). */
	version?: string | null,
};

/**  One FC's USB heat timer. It runs while the FC is on USB with its battery in. */
export type UsbTimer = {
	port: string,
	id: string | null,
	/**  A battery is in (the FC reads more than 1 V on its battery lead). */
	battery: boolean,
	volts: number | null,
	/**  Seconds on USB with the battery in. */
	elapsed_s: number,
	/**  The limit in seconds; None when the timer is off (`gearUsbMinutes` 0). */
	limit_s: number | null,
	/**  Seconds left; 0 once past the limit. */
	remaining_s: number | null,
	/**  "Unplug now" played for this battery session. */
	warned: boolean,
};

